// CalcLayer.jsx
import React from 'react';
import { Image } from 'react-konva';
import useImage from 'use-image';

const CalcLayer = ({ src, x = 0, y = 0, width, height }) => {
  const [image] = useImage(src);
  return (
    <Image
      image={image}
      x={x}
      y={y}
      width={width}
      height={height}
      listening={false} // Ajoutez ceci
    />
  );
};

export default CalcLayer;
