// MGA/src/pages/PostBatailleDetail.jsx
import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import Header from "../components/HeaderS";
import postBatailleData from "../data/postBatailleData"; // Assurez-vous que la casse correspond
import Exploration from "./Exploration";

const PostBatailleDetail = () => {
  const { type } = useParams(); // Récupère le paramètre dynamique de l'URL
  const navigate = useNavigate();

  // Récupère les données associées au type de post-bataille
  const postBataille = postBatailleData[type?.toLowerCase()];


  // Si le type de post-bataille n'existe pas, afficher un message d'erreur
  if (!postBataille) {
    return (
      <div className="homepage">
        <Header />
        <div className="home-content">
          <h1>Erreur</h1>
          <p>Ouups, ce type de post-bataille n'existe pas !</p>
          <button onClick={() => navigate("/post-bataille")}>Retour</button>
        </div>
      </div>
    );
  }

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
        {/* En-tête avec titre et sous-titre */}
        <div className="detail-header">
          <div className="detail-title"><h1>{postBataille.title}</h1>
          </div>
          <div className="detail-subtitle"><h2>{postBataille.subtitle.split("\n").map((line, i) => (
                <React.Fragment key={i}>
                  {line}
                  <br />
                </React.Fragment>
              ))}
            </h2>
          </div>
        </div>

        {/* Affichage du contenu pour les autres types (sauf exploration) */}
        {type === "exploration" ? (
          // On affiche le composant Exploration si nécessaire
          <Exploration />
        ) : (
          <>

           {/* Afficher la liste des hits */}
           {postBataille.hits && (
              <div className="hits">
                {postBataille.hits.map((hit, index) => (
                  <div key={index} className="hit">
                    <h3 className={`hit-title ${hit.className || ""}`}>
                      {hit.title}
                    </h3>
                    <p className="hit-description">
                      {hit.description.split("\n").map((line, i) => (
                        <React.Fragment key={i}>
                          {line}
                          <br />
                        </React.Fragment>
                      ))}
                    </p>
                  </div>
                ))}
              </div>
            )}

            {/* Afficher le tableau (tab) si présent */}
            {postBataille.tab && (
              <div className="table-container">
              <table className="detail-table">
                <tbody>
                  {postBataille.tab.map((row, rowIndex) => (
                    <tr key={rowIndex}>
                      {row.map((cell, cellIndex) => (
                        <td key={cellIndex}>{cell}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
              </div>
            )}

           
          </>
        )}

        {/* Boutons de navigation fluides */}
        <div className="navigation-buttons">
          {postBataille.previous && (
            <button
              className="nav-btn nav-prev"
              onClick={() => navigate(`/post-bataille/${postBataille.previous}`)}
            >
              ᐊ {postBataille.previousTitle}
            </button>
          )}
          <button
            className="nav-btn nav-return"
            onClick={() => navigate("/post-bataille")}
          >
            Retour
          </button>
          {postBataille.next && (
            <button
              className="nav-btn nav-next"
              onClick={() => navigate(`/post-bataille/${postBataille.next}`)}
            >
              {postBataille.nextTitle} ᐅ
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default PostBatailleDetail;