import React from "react";
import { useNavigate } from "react-router-dom";
import Header from "../components/HeaderS";
import "../pages/HomePage.css"; // Réutilisation du CSS de HomePage


const Critiques = () => {
  const navigate = useNavigate();

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
        <div className="detail-header">
        <div className="detail-title"><h1>Coups Critiques</h1></div>
        <div className="detail-subtitle"><h2>Sur un '6' au jet pour blesser :<br /><i>(1x par phase de CàC max)</i></h2></div>
        </div>
        <div className="menu">
          <button onClick={() => navigate("/coups-critiques/generiques")}>Critiques Génériques 💣
            <span className="button-subtext">(Et un peu trop fort)</span></button>
          <button onClick={() => navigate("/coups-critiques/tranchants")}>Armes Tranchantes 🔪 
            <div className="button-subtext">Épées, haches,...</div></button>
          <button onClick={() => navigate("/coups-critiques/contondants")}>Armes Contondantes 🔨
            <span className="button-subtext">Masses, marteaux, fléaux,...</span>
          </button>
          <button onClick={() => navigate("/coups-critiques/naturelles")}>Armes Naturelles&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;🍃
            <span className="button-subtext">Animaux, zombies, possédés,...</span>
          </button>
          <button onClick={() => navigate("/coups-critiques/estocs")}>Armes d'Estoc&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;🍢
            <span className="button-subtext">Lances, hallbardes,...</span>
          </button>
          <button onClick={() => navigate("/coups-critiques/tir")}>Armes de Tir&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;🏹
            <span className="button-subtext">Arcs, arbalètes, armes de jet,...</span>
          </button>
          <button onClick={() => navigate("/coups-critiques/maison")}>Coups Critiques<br />Règles Maison&nbsp;&nbsp;&nbsp;&nbsp;🏚️
          <span className="button-subtext">Plus équilibrés et moins puissants.</span>
          </button>
        </div>
        
        <button 
    className="nav-btn nav-return" 
    onClick={() => navigate("/")}
  >
    Retour
  </button>  

      </div>
    </div>
  );
};

export default Critiques;
