// MenuCalques.jsx
import React from 'react';
import './MapPage.css'; // si tu utilises le fichier CSS associé

const MenuCalques = ({ calquesTours, setCalquesTours }) => {
  const handleChange = (layer) => {
    setCalquesTours((prev) => ({
      ...prev,
      [layer]: !prev[layer],
    }));
  };

  return (
    <div className="menuCalques">
      <h4>Calques</h4>
      <div>
        <input 
          type="checkbox" 
          checked={calquesTours.layer1} 
          onChange={() => handleChange('layer1')}
          id="layer1"
        />
        <label htmlFor="layer1">1 ère Partie</label>
      </div>
      <div>
        <input 
          type="checkbox" 
          checked={calquesTours.layer2} 
          onChange={() => handleChange('layer2')}
          id="layer2"
        />
        <label htmlFor="layer2">2 ème Partie</label>
      </div>
      <div>
        <input 
          type="checkbox" 
          checked={calquesTours.layer3} 
          onChange={() => handleChange('layer3')}
          id="layer3"
        />
        <label htmlFor="layer3">État Actuel</label>
      </div>
    </div>
  );
};

export default MenuCalques;
