// src/pages/BandesDetail.jsx
import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import Header from "../components/HeaderS";
import bandesData from "../data/bandesData"; // Import des données maison

const Bandes = () => {
  const { subType } = useParams(); // On suppose que l'URL sera du genre /critiqon/:subType
  const navigate = useNavigate();

  const bandes = bandesData[subType];

  if (!bandes) {
    return (
      <div className="homepage">
        <Header />
        <div className="home-content">
          <h1>Erreur</h1>
          <p>Envois un petit descriptif j'ai dis!</p>
          <button onClick={() => navigate("/bandes")}>Retour</button>
        </div>
      </div>
    );
  }

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
      <div className="detail-header">
        <div className="detail-title"><h1>{bandes.title}</h1>
          <div className="detail-subtitle"><h2>{bandes.subtitle.split("\n").map((line, i) => (
              <React.Fragment key={i}>
                {line}
                <br />
              </React.Fragment>
            ))}
          </h2>
        </div>
        </div>
        </div>

                <div className="hits">
                  {bandes.hits.map((hit, index) => (
                    <div key={index} className="hit">
                      <h3 className={`hit-title ${hit.className || ""}`}>
                      {hit.title}
                    </h3>
                      <p className="hit-description">
                        {hit.description.split("\n").map((line, i) => (
                          <React.Fragment key={i}>
                            {line}
                            <br />
                          </React.Fragment>
                        ))}
                      </p>
                    </div>
                  ))}
                </div>
        
                {/* Boutons de navigation fluides */}
                <div className="navigation-buttons">
          {bandes.previous && (
            <button 
              className="nav-btn nav-prev" 
              onClick={() => navigate(`/campagne/bandes/${bandes.previous}`)}
            >
              ᐊ {bandes.previousTitle}
            </button>
          )}
          <button 
            className="nav-btn nav-return" 
            onClick={() => navigate("/campagne/bandes")}
          >
            Retour
          </button>
          {bandes.next && (
            <button 
              className="nav-btn nav-next" 
              onClick={() => navigate(`/campagne/bandes/${bandes.next}`)}
            >
              {bandes.nextTitle} ᐅ
            </button>
          )}
        </div>
        
                </div>
              </div>
          );
        };
        
        export default Bandes;


