// MGA/src/pages/CritiquesDetail.jsx
import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import Header from "../components/HeaderS";
import critiquesData from "../data/critiquesData"; // Import des données

const CritiquesDetail = () => {
  const { type } = useParams(); // Récupère le paramètre dynamique de l'URL
  const navigate = useNavigate();

  // Récupère les données associées à ce type de critique
  const critique = critiquesData[type];

  // Si le type de critique n'existe pas, afficher un message d'erreur
  if (!critique) {
    return (
      <div className="homepage">
        <Header />
        <div className="home-content">
          <h1>Erreur</h1>
          <p>Ce type de critique n'existe pas !</p>
          <button onClick={() => navigate("/coups-critiques")}>Retour</button>
        </div>
      </div>
    );
  }

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
      <div className="detail-header">
        <div className="detail-title"><h1>{critique.title}</h1>
          <div className="detail-subtitle"><h2>{critique.subtitle.split("\n").map((line, i) => (
              <React.Fragment key={i}>
                {line}
                <br />
              </React.Fragment>
            ))}
          </h2>
        </div>
        </div>
        </div>

        <div className="hits">
          {critique.hits.map((hit, index) => (
            <div key={index} className="hit">
              <p className="hit-title">{hit.title}</p>
              <p className="hit-description">
                {hit.description.split("\n").map((line, i) => (
                  <React.Fragment key={i}>
                    {line}
                    <br />
                  </React.Fragment>
                ))}
              </p>
            </div>
          ))}
        </div>

{/* Boutons de navigation fluides */}
        <div className="navigation-buttons">
  {critique.previous && (
    <button 
      className="nav-btn nav-prev" 
      onClick={() => navigate(`/coups-critiques/${critique.previous}`)}
    >
      ᐊ {critique.previousTitle}
    </button>
  )}
  <button 
    className="nav-btn nav-return" 
    onClick={() => navigate("/coups-critiques")}
  >
    Retour
  </button>
  {critique.next && (
    <button 
      className="nav-btn nav-next" 
      onClick={() => navigate(`/coups-critiques/${critique.next}`)}
    >
      {critique.nextTitle} ᐅ
    </button>
  )}
</div>

        </div>
      </div>
  );
};

export default CritiquesDetail;
