import React from "react";
import { useNavigate, Outlet } from "react-router-dom";
import Header from "../components/Header";
import "./HomePage.css"; // Vérifie que ce fichier existe !

const HomePage = () => {
  const navigate = useNavigate();

  console.log("HomePage is rendering"); // ✅ TEST

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
        <h1>Construction en cours</h1>
        <div className="menu">
          <button onClick={() => navigate("/regles")}>Règles</button>
          <button onClick={() => navigate("/coups-critiques")}>Coups Critiques</button>
          <button onClick={() => navigate("/post-bataille")}>Post Bataille</button>
          <button onClick={() => navigate("/objets-equipements")}>Objets et Équipements</button>
          <button onClick={() => navigate("/competences-sorts-prieres")}>Compétences et Sorts</button>
          <button onClick={() => navigate("/regles-speciales")}>Règles Spéciales</button>
          <button onClick={() => navigate("/campagne")}>Campagne</button>
        </div>
      </div>
      <Outlet />
    </div>
  );
};

export default HomePage;
