// src/components/Header.jsx
import React from "react";
import headerTitle from "../headerTitle.png"; // Vérifie que l'image existe !
import "../pages/HomePage.css"; // Vérifie ce chemin aussi !

const Header = ({ onTitleClick }) => {
  return (
    <header className="header">
      <div className="header-main">
        <img
          src={headerTitle}
          alt="Mordheim Game Assist"
          className="header-title"
          onClick={onTitleClick}
        />
      </div>
    </header>
  );
};

export default Header; // ✅ Il faut ce export !


