// src/pages/ExplorationDetail.jsx
import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import Header from "../components/HeaderS";
import explorationData from "../data/explorationData";

const Exploration = () => {
  const { subType } = useParams(); // On suppose que l'URL sera du genre /coups-critiques/maison/:subType
  const navigate = useNavigate();

  const exploration = explorationData[subType];

  if (!exploration) {
    return (
      <div className="homepage">
        <Header />
        <div className="home-content">
          <h1>Erreur</h1>
          <p>ça n'existe pas !</p>
          <button onClick={() => navigate("/post-bataille/exploration")}>Retour</button>
        </div>
      </div>
    );
  }

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
      <div className="detail-header">
        <div className="detail-title"><h1>{exploration.title}</h1>
          <div className="detail-subtitle"><h2>{exploration.subtitle.split("\n").map((line, i) => (
              <React.Fragment key={i}>
                {line}
                <br />
              </React.Fragment>
            ))}
          </h2>
        </div>
        </div>
        </div>

                <div className="hits">
                  {exploration.hits.map((hit, index) => (
                    <div key={index} className="hit">
                      <p className="hit-title">{hit.title}</p>
                      <p className="hit-description">
                        {hit.description.split("\n").map((line, i) => (
                          <React.Fragment key={i}>
                            {line}
                            <br />
                          </React.Fragment>
                        ))}
                      </p>
                    </div>
                  ))}
                </div>
        
                {/* Boutons de navigation fluides */}
                <div className="navigation-buttons">
          {exploration.previous && (
            <button 
              className="nav-btn nav-prev" 
              onClick={() => navigate(`/post-bataille/exploration/${exploration.previous}`)}
            >
              ᐊ {exploration.previousTitle}
            </button>
          )}
          <button 
            className="nav-btn nav-return" 
            onClick={() => navigate("/post-bataille/exploration")}
          >
            Retour
          </button>
          {exploration.next && (
            <button 
              className="nav-btn nav-next" 
              onClick={() => navigate(`/post-bataille/exploration/${exploration.next}`)}
            >
              {exploration.nextTitle} ᐅ
            </button>
          )}
        </div>
        
                </div>
              </div>
          );
        };
        
        export default Exploration;


