import React from "react";
import { useNavigate } from "react-router-dom";
import Header from "../components/HeaderS";
import "../pages/HomePage.css";

const CritiquesMaison = () => {
  const navigate = useNavigate();

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
        <div className="detail-header">
        <div className="detail-title"><h1>Coups Critiques<br />Maison</h1></div>
        <div className="detail-subtitle"><h2>Sur un '6' au jet pour blesser :<br /><i>(1x par phase de CàC max)</i></h2></div>
        </div>
        <div className="menu">
          <button onClick={() => navigate("/coups-critiques/maison/tranchant")}>Armes Tranchantes 🔪 
            <div className="button-subtext">Épées, haches,...</div></button>
          <button onClick={() => navigate("/coups-critiques/maison/contondant")}>Armes Contondantes 🔨
            <span className="button-subtext">Masses, marteaux, fléaux,...</span></button>
          <button onClick={() => navigate("/coups-critiques/maison/naturelle")}>Armes Naturelles&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;🍃
            <span className="button-subtext">Dague, zombies, possédés,...</span></button>
          <button onClick={() => navigate("/coups-critiques/maison/estoc")}>Armes d'Estoc&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;🍢
            <span className="button-subtext">Lances, hallbardes,...</span></button>
          <button onClick={() => navigate("/coups-critiques/maison/tir")}>Armes de Tir&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;🏹
            <span className="button-subtext">Arcs, arbalètes, armes de jet,...</span></button>
          <button onClick={() => navigate("/coups-critiques/maison/poudreNoir")}>Armes à poudre noir 💣
            <span className="button-subtext">Pistolets, arquebuse,...</span></button>
          
        </div>

        
   {/* Boutons de navigation fluides */}
   <div className="navigation-buttons">
  

  <button 
    className="nav-btn nav-return" 
    onClick={() => navigate("/coups-critiques")}
  >
    Retour
  </button>
  
</div>

        </div>
      </div>
  );
};



export default CritiquesMaison;
