//MGA/src/subMenus/PostBataille.jsx
import React from "react";
import { useNavigate } from "react-router-dom";
import Header from "../components/HeaderS";
import "../pages/HomePage.css"; // Réutilisation du CSS de HomePage


const PostBataille = () => {
  const navigate = useNavigate();

  return (
    <div className="homepage">
      <Header />
      <div className="home-content">
        <div className="detail-header">
        <div className="detail-title"><h1>Post-Bataille</h1></div>
        <div className="detail-subtitle"><h2>Suivre les étapes<br />dans l'ordre.</h2></div>
        </div>
        <div className="menu">
          <button onClick={() => navigate("/post-bataille/blessuresgraves")}>Blessures Graves 🚑
            <span className="button-subtext">J'ai beau être matinal...</span></button>
          <button onClick={() => navigate("/post-bataille/experience")}>Expérience et Lvl-Up 📈
            <div className="button-subtext">Xp, xp, xp ,...</div></button>
          <button onClick={() => navigate("/post-bataille/exploration")}>Exploration 🗺️
            <span className="button-subtext">Doubles, triples, foules,...</span>
          </button>
          <button onClick={() => navigate("/post-bataille/vente")}>Vente de Butin&nbsp;&nbsp; 💰
            <span className="button-subtext">Tu peux garder la monnaie !</span>
          </button>
          <button onClick={() => navigate("/post-bataille/recrutement")}>Recrutement 👨‍🎓
            <span className="button-subtext">Engagez-vous qu'y disait !</span>
          </button>
          <button onClick={() => navigate("/post-bataille/commerce")}>Commerce 🛍️
            <span className="button-subtext">Pimp ton crew !</span>
          </button>
        </div>

        <button 
    className="nav-btn nav-return" 
    onClick={() => navigate("/")}
  >
    Retour
  </button> 

      </div>
    </div>
  );
};

export default PostBataille;
