// src/components/Header.jsx
import React from "react";
import { useNavigate } from "react-router-dom";
import headerTitle from "../headerTitleS.png"; // Assure-toi que le chemin est correct
import "../pages/HomePage.css";

const HeaderS = () => {
    const navigate = useNavigate();
    
    return (
      <header className="headerS" onClick={() => navigate("/")}>
        <div className="headers-main">
          <img
            src={headerTitle}
            alt="Mordheim Game Assist"
            className="headers-title"
          />
        </div>
      </header>
    );
  };
  
  export default HeaderS;


