// MGA/src/App.jsx
import { Routes, Route } from "react-router-dom";
import HomePage from "./pages/HomePage";
import Regles from "./subMenus/Regles"; // Import du menu des règles
import CoupsCritiques from "./subMenus/CoupsCritiques";
import CritiquesDetail from "./pages/CritiquesDetail";  // Assure-toi que ce fichier existe
import CritiquesMaison from "./pages/CritiquesMaison"; 
import CritiquesMaisonDetail from "./pages/CritiquesMaisonDetail";
import PostBataille from "./subMenus/PostBataille";
import ObjetsEquipements from "./subMenus/ObjetsEquipements";
import CompetencesSortsPrieres from "./subMenus/CompetencesSortsPrieres";
import ReglesSpeciales from "./subMenus/ReglesSpeciales";
import Campagne from "./subMenus/Campagne";
import PostBatailleDetail from "./pages/PostBatailleDetail";
import ExplorationDetail from "./pages/ExplorationDetail";
import Exploration from "./pages/Exploration";
import MapPage from "./pages/MapPage";
import Bandes from "./pages/Bandes";
import BandesDetail from "./pages/BandesDetail";  
import CampagneDetail from "./pages/CampagneDetail";



function App() {
  return (
    <Routes>
      <Route path="/" element={<HomePage />} />
      <Route path="/regles" element={<Regles />} />
      <Route path="/coups-critiques" element={<CoupsCritiques />} />
      <Route path="/coups-critiques/:type" element={<CritiquesDetail />} />
      <Route path="/coups-critiques/maison" element={<CritiquesMaison />} />
      <Route path="/coups-critiques/maison/*" element={<CritiquesMaison />} />
      <Route path="/coups-critiques/maison/:subType" element={<CritiquesMaisonDetail />} />
      <Route path="/post-bataille" element={<PostBataille />} />
      <Route path="/post-bataille/:type" element={<PostBatailleDetail />} />
      <Route path="/post-bataille/exploration/*" element={<Exploration />} />
      <Route path="/post-bataille/exploration/:subType" element={<ExplorationDetail />} />
      <Route path="/objets-equipements" element={<ObjetsEquipements />} />
      <Route path="/competences-sorts-prieres" element={<CompetencesSortsPrieres />} />
      <Route path="/regles-speciales" element={<ReglesSpeciales />} />
      <Route path="/campagne" element={<Campagne />} />
      <Route path="/campagne/:type" element={<CampagneDetail />} />
      <Route path="/campagne/carte/*" element={<MapPage />} />
      <Route path="/campagne/bandes/*" element={<Bandes />} />
      <Route path="/campagne/bandes/:subType" element={<BandesDetail />} />
      
      
    </Routes>
  );
}

export default App;


