
// MapPage.jsx
import React, { useState } from 'react';
import { Stage, Layer, Image as KonvaImage } from 'react-konva';
import useImage from 'use-image';
import MenuCalques from './MenuCalques';
import CalcLayer from './CalcLayer';
import './MapPage.css';

const MapPage = () => {
  // Gestion du menu et des calques
  const [menuVisible, setMenuVisible] = useState(false);
  const [calquesTours, setCalquesTours] = useState({
    layer1: false,
    layer2: false,
    layer3: true,
  });
  
  // État pour la zone active (celle cliquée)
  const [activeZone, setActiveZone] = useState(null);

  // Charge l'image de la carte
  const [bgImage] = useImage(process.env.PUBLIC_URL + '/carte.png');
  const stageWidth = bgImage ? bgImage.width : window.innerWidth;
  const stageHeight = bgImage ? bgImage.height : window.innerHeight;

  // Définition des zones interactives
  const zones = [
    { id: 'zone1', title: 'Porte Ouest', text: 'Recevez 5 CO des joueurs livrant bataille dans un quartier adjacent', xMin: 35, xMax: 139, yMin: 140, yMax: 260 },
    { id: 'zone2', title: 'Le Quartier Nain', text: '(Nain : +1 Fragment et Scénario Bonus 🍺)\n1/2 prix pour recruter un Tueur Nain\n1/2 prix pour la Bière de Bugman, les Armes et Armures en Gromril', xMin: 10, xMax: 120, yMin: 278, yMax: 405 },
    { id: 'zone3', title: 'Jardins du Souvenir', text: "(Gobs des Forêts : +1 Fragment et Scénario Bonus 🕷️)\nLancez 3D6 (au lieu de 2) pour recruter de nouvelles recrues aux groupes d'Hommes de main NON-humains déjà existants.", xMin: 180, xMax: 287, yMin: 212, yMax: 320 },
    { id: 'zone4', title: 'Quartier des Artisants', text: "1/2 prix pour : les Habits en soie de Cathay, les Flèches de chasse, les Lanternes, les Filets, les Cordes & Grappins et la Poudre noire supérieure.", xMin: 133, xMax: 224, yMin: 338, yMax: 438 },
    { id: 'zone5', title: 'Les Geôles', text: "(Répurgateurs/Dam. : +1 Fragment et Scénario Bonus ⛓️)\n☄️ +1 Fragment\n1/2 prix pour : recruter un Geôlier. Sur le Tableau des Blessures Graves, si l'un de vos Héros obtient le résultat 61 Capturé, remplacez-le par 41-55 Récupération totale.", xMin: 65, xMax: 179, yMin: 455, yMax: 571 },
    { id: 'zone6', title: 'Baraquements du Corbeau', text: " 1/2 prix pour recruter un Garde du corps Ogre\nRevente des armes/amrures au prix d'achat", xMin: 215, xMax: 315, yMin: 12, yMax: 127 },
    { id: 'zone7', title: 'Statue du comte Gotthard', text: "(Averlanders : +1 Fragment et Scénario Bonus 🗿)\n Le Chef de la bande gagne +1 en Cd. ", xMin: 446, xMax: 537, yMin: 40, yMax: 140 },
    { id: 'zone8', title: 'Le Quartier Riche', text: "⚔️ Zone contestée : Pas d'infuence,\n☄️+1 Fragment\nVous trouvez la quantité maximale d'or ou d'équipement sur l'un des résultats du Tableau d'Exploration.", xMin: 320, xMax: 420, yMin: 144, yMax: 250 },
    { id: 'zone9', title: 'Palais du Comte Steinhardt', text: "☄️+1 Fragment\n1/2 prix pour recruter un Chevalier Solitaire.\n1/2 prix sur les Chevaux, les Destriers et les Chiens de guerre.", xMin: 307, xMax: 420, yMin: 284, yMax: 418 },
    { id: 'zone10', title: 'Place des Exécutions', text: "(Répurgateurs/Ced. : +1 Fragment et Scénario Bonus 🪝)\n⚔️ Zone contestée : Pas d'infuence\n☄️+1 Fragment\nLancez un dé supplémentaire lors de la Procédure d'Exploration. ", xMin: 255, xMax: 379, yMin: 433, yMax: 549 },
    { id: 'zone11', title: 'Cimetière de Saint Voller', text: "(Morts-Vivants : +1 Fragment et Scénario Bonus 🧟‍♂️)\n☄️+1 Fragment\nMorts-Vivants : Recruter des Zombies coûte 10 CO et 30 CO pour des Goules.\nAutres bandes : La bande devient immunisée à la Peur. ", xMin: 200, xMax: 270, yMin: 600, yMax: 675 },
    { id: 'zone12', title: 'Temple de Morr', text: "Sur le Tableau des Blessures Graves, si l'un de vos Héros obtient le résultat 11-15 Mort, remplacez-le par 41-55 Récupération totale. ", xMin: 277, xMax: 350, yMin: 609, yMax: 700 },
    { id: 'zone13', title: 'Pont du Milieu ', text: "☄️+1 Fragment\nLa bande qui contrôle le pont instaure un péage.\nElle gagne 2D6 Couronnes d'Or si une autre bande passe par le pont pour atteindre le lieu de la bataille.", xMin: 450, xMax: 545, yMin: 285, yMax: 385 },
    { id: 'zone14', title: 'Le Rock', text: "(Orques : +1 Fragment et Scénario Bonus 🧌)\n☄️+1 Fragment\nLorsque vous vendez des pierres magiques dans ce quartier, vous gagnez +20% de Couronne d'Or, arrondi à l'inférieur.", xMin: 457, xMax: 575, yMin: 495, yMax: 609 },
    { id: 'zone15', title: 'Porte de la Rivière', text: "Recevez 5 CO des joueurs livrant bataille dans un quartier adjacent", xMin: 640, xMax: 760, yMin: 2, yMax: 85 },
    { id: 'zone16', title: 'Les Quais', text: "(Pirates : +1 Fragment et Scénario Bonus 🏴‍☠️)\nLancez 3D6 (au lieu de 2) pour recruter de nouvelles recrues aux groupes d'Hommes de main humains déjà existants.", xMin: 610, xMax: 719, yMin: 105, yMax: 221 },
    { id: 'zone17', title: 'Quartier des Marchands', text: "(Elfes : +1 Fragment et Scénario Bonus 🧝‍♂️)\n☄️+1 Fragment\n1/2 prix pour recruter un Éclaireur Elfe.\n1/2 prix sur les Arcs elfiques, les Capes elfiques, les armes et armures en Ithilmar.", xMin: 598, xMax: 718, yMin: 241, yMax: 344 },
    { id: 'zone18', title: 'Amphithéâtre', text: "1/2 prix pour recruter un Gladiateur.\n1/2 prix sur les Filets.\n Blessures Graves: Si l'un de vos Héros obtient le résultat 65 Vendu aux arènes, il gagne automatiquement le combat.", xMin: 609, xMax: 726, yMin: 398, yMax: 511 },
    { id: 'zone19', title: 'Porte Sud', text: "Recevez 5 CO des joueurs livrant bataille dans un quartier adjacent", xMin: 565, xMax: 670, yMin: 617, yMax: 724 },
    { id: 'zone20', title: 'Grande Librairie', text: "1/2 prix sur les Livres de cuisine Halfling, les Livres Saints, les Cartes de Mordheim et les Grimoires de Magie.", xMin: 873, xMax: 1008, yMin: 43, yMax: 179 },
    { id: 'zone21', title: 'Place du Marché', text: "⚔️ Zone contestée : Pas d'infuence,\n☄️+1 Fragment\nAjoutez +2 sur le test de disponibilité des objets rares. ", xMin: 797, xMax: 911, yMin: 278, yMax: 396 },
    { id: 'zone22', title: 'La Fosse', text: "⚔️ Zone contestée : Pas d'infuence,\n☄️+1 Fragment\nExploration: Vous pouvez le remplacer votre résultat par 'La Fosse (1⁶)'.Mais le Héro est dévoré sur un 1 ou 2 au lieu de 1. S'il n'est pas dévoré, les Possédés reviennent toujours avec 7 fragments. ", xMin: 785, xMax: 910, yMin: 439, yMax: 570 },
    { id: 'zone23', title: 'Le Quartier Pauvre', text: "⚔️ Zone contestée : Pas d'infuence,\nLancez un dé supplémentaire lors de la Procédure d'Exploration. ", xMin: 726, xMax: 850, yMin: 582, yMax: 705 },
    { id: 'zone24', title: 'Hostel de Ville', text: "Pendant la Procédure d'Exploration, vous pouvez modifier un dé de +1 ou -1. ", xMin: 930, xMax: 1200, yMin: 270, yMax: 370 },
    { id: 'zone25', title: 'Le Petit Moot', text: "(Gobs de la Nuit : +1 Fragment et Scénario Bonus 🍄)\n1/2 prix pour recruter un Éclaireur Halfling.\n1/2 prix sur les Livres de cuisine Halfling. ", xMin: 1050, xMax: 1150, yMin: 80, yMax: 190 },
    { id: 'zone26', title: 'Temple de Sigmar', text: "Sur le Tableau des Blessures Graves, si l'un de vos Héros obtient un résultat entre 22 et 35, lancez 1D6. Sur 5+, le résultat est remplacé par 45-55 Récupération Totale. ", xMin: 1040, xMax: 1159, yMin: 233, yMax: 345 },
    { id: 'zone27', title: 'Manoir des Sorciers', text: "1/2 prix pour recruter un Mage.\n1/2 prix sur les Grimoires de Magie. Vous pouvez choisir un sort plutôt que de le générer aléatoirement. ", xMin: 1008, xMax: 1108, yMin: 405, yMax: 517 },
    { id: 'zone28', title: 'Porte Est', text: "Recevez 5 CO des joueurs livrant bataille dans un quartier adjacent", xMin: 1120, xMax: 1205, yMin: 393, yMax: 483 },
    { id: 'zone29', title: "Tour de l'Horloge", text: "⚔️ Zone contestée : Pas d'infuence,\n☄️+1 Fragment\nVous trouvez la quantité maximale d'or ou d'équipement sur l'un des résultats du Tableau d'Exploration.", xMin: 900, xMax: 1010, yMin: 555, yMax: 675 },
    { id: 'zone29', title: "L'Allée aux Clôture", text: "1/2 prix sur les Poisons et Drogues", xMin: 767, xMax: 871, yMin: 155, yMax: 260 },
// Ajoutez ici les autres zones...
  ];

  // Gestionnaire de clic sur le Stage
  const handleStageClick = (e) => {
    const pos = e.target.getStage().getPointerPosition();
    const foundZone = zones.find(zone =>
      pos.x >= zone.xMin &&
      pos.x <= zone.xMax &&
      pos.y >= zone.yMin &&
      pos.y <= zone.yMax
    );
    setActiveZone(foundZone || null);
  };

  return (
    <div className="mapPageContainer">
      {/* Bouton pour afficher/masquer le menu */}
      <button 
        onClick={() => setMenuVisible(!menuVisible)}
        className="menuButton"
      >
        {menuVisible ? 'Masquer le menu' : 'Afficher le menu'}
      </button>
      
      {/* Menu des calques placé sous le bouton */}
      {menuVisible && (
        <div className="menuCalquesContainer">
          <MenuCalques calquesTours={calquesTours} setCalquesTours={setCalquesTours} />
        </div>
      )}

      {/* Stage avec la carte et les layers */}
      <Stage width={stageWidth} height={stageHeight} onClick={handleStageClick} onTap={handleStageClick}>
        {/* Calque de fond : la carte */}
        <Layer>
          <KonvaImage
            image={bgImage}
            x={0}
            y={0}
            width={stageWidth}
            height={stageHeight}
            listening={false}
          />
        </Layer>
        {/* Calques superposés */}
        {calquesTours.layer1 && (
          <Layer>
            <CalcLayer
              src={process.env.PUBLIC_URL + '/calc/layer1.png'}
              x={0}
              y={0}
              width={stageWidth}
              height={stageHeight}
            />
          </Layer>
        )}
        {calquesTours.layer2 && (
          <Layer>
            <CalcLayer
              src={process.env.PUBLIC_URL + '/calc/layer2.png'}
              x={0}
              y={0}
              width={stageWidth}
              height={stageHeight}
            />
          </Layer>
        )}
        {calquesTours.layer3 && (
          <Layer>
            <CalcLayer
              src={process.env.PUBLIC_URL + '/calc/layer3.png'}
              x={0}
              y={0}
              width={stageWidth}
              height={stageHeight}
            />
          </Layer>
        )}
        {/* Vous pouvez ajouter un Layer transparent si vous voulez visualiser la zone cliquée pour le débuggage */}
      </Stage>

      {/* Cadre d'information qui s'affiche en bas de la carte */}
      {activeZone && (
        <div className="zoneFrame">
          <h3>{activeZone.title}</h3>
          <p>{activeZone.text}</p>
        </div>
      )}
    </div>
  );
};

export default MapPage;
